"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Navigation } from "@/components/Navigation";
import { LandingView } from "@/components/LandingView";
import { CapabilitiesSection } from "@/components/CapabilitiesSection";
import { ArchitectureSection } from "@/components/ArchitectureSection";
import { DashboardView } from "@/components/DashboardView";
import { Footer } from "@/components/Footer";
import { SmoothScrollProvider } from "@/components/SmoothScrollProvider";

export default function Home() {
  const [isLanding, setIsLanding] = useState(true);

  return (
    <SmoothScrollProvider>
      <main className="w-full min-h-screen bg-[#050505] overflow-x-hidden">
        <AnimatePresence mode="wait">
          {isLanding ? (
            <motion.div key="landing" exit={{ opacity: 0, scale: 0.95 }} transition={{ duration: 0.5 }}>
              {/* Shared Navigation — anchor-based smooth scrolling */}
              <Navigation />

              {/* All sections stacked on one page */}
              <LandingView onEnterAegis={() => setIsLanding(false)} />
              <CapabilitiesSection />
              <ArchitectureSection />
              <Footer />
            </motion.div>
          ) : (
            <DashboardView key="dashboard" onBackToHome={() => setIsLanding(true)} />
          )}
        </AnimatePresence>
      </main>
    </SmoothScrollProvider>
  );
}

